import scipy.optimize as so
def design(th,gkind):
    k,p=th[0],th[1]
    if gkind=='tanh': g=np.tanh(k*t**p)
    elif gkind=='exp': g=1-np.exp(-k*t**p)
    elif gkind=='mm': g=t**p/(k+t**p)
    cols=[g*P,P,P**2,P**3,g*P**2,g,g*P**3,P*t,t]
    return np.column_stack(cols)
