import itertools, scipy.optimize as so
names=['G','G*P','G*P2','G*P3','P','P2','P3','P*t','P2*t','P3*t','t','G*t','P*t2']
def basis(th):
    k=th[0]; G=np.tanh(k*t)
    d={'G':G,'G*P':G*P,'G*P2':G*P**2,'G*P3':G*P**3,'P':P,'P2':P**2,'P3':P**3,'P*t':P*t,'P2*t':P**2*t,'P3*t':P**3*t,'t':t,'G*t':G*t,'P*t2':P*t**2}
    return d
def L(th,cols):
    d=basis(th); A=np.column_stack([np.ones_like(t)]+[d[c] for c in cols])
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@c)**2)/np.var(dP_dt)
res=[]
for n in [4,5]:
