import scipy.optimize as so
def des(th):
    k=th[0]; G=np.tanh(k*t)
    return np.column_stack([G,G*P,G*P**2,G*P**3,P,P**2,P**3,P*t,P*t**2,P**2*t,t,P*G*t])
def L(th):
    A=des(th); c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@c)**2)/np.var(dP_dt)
